import collections

def shortest_path_binary(grid):
    n = len(grid)
    if grid[0][0] or grid[n - 1][n - 1]: return -1
    dist = [[0] * n for _ in range(n)]; dist[0][0] = 1; q = collections.deque([(0, 0)])
    while q:
        y, x = q.popleft()
        if (y, x) == (n - 1, n - 1): return dist[y][x]
        for dy in (-1, 0, 1):
            for dx in (-1, 0, 1):
                yy, xx = y + dy, x + dx
                if 0 <= yy < n and 0 <= xx < n and not grid[yy][xx] and not dist[yy][xx]:
                    dist[yy][xx] = dist[y][x] + 1; q.append((yy, xx))
    return -1

