int shortestPathBinaryMatrix(vector<vector<int>>& g) {
    int n = g.size(); if (g[0][0] || g[n-1][n-1]) return -1;
    vector<vector<int>> d(n, vector<int>(n, 0)); d[0][0] = 1; deque<pair<int,int>> q{{0, 0}};
    while (!q.empty()) { auto [y, x] = q.front(); q.pop_front(); if (y == n - 1 && x == n - 1) return d[y][x];
        for (int dy = -1; dy <= 1; dy++) for (int dx = -1; dx <= 1; dx++) { int yy = y + dy, xx = x + dx; if (yy >= 0 && yy < n && xx >= 0 && xx < n && !g[yy][xx] && !d[yy][xx]) { d[yy][xx] = d[y][x] + 1; q.push_back({yy, xx}); } } }
    return -1;
}
